import{_ as t,o as s,c as r,a3 as a}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse(`{"title":"Désactiver les surcharges d'image des entités","description":"Découvrez comment désactiver les surcharges d'image des entités et quand utiliser cette option de performance.","frontmatter":{"title":"Désactiver les surcharges d'image des entités","description":"Découvrez comment désactiver les surcharges d'image des entités et quand utiliser cette option de performance."},"headers":[],"relativePath":"fr/projects/uix/extras/disable-entity-picture-image-override.md","filePath":"fr/projects/uix/extras/disable-entity-picture-image-override.md","lastUpdated":1793108161000}`),i={name:"fr/projects/uix/extras/disable-entity-picture-image-override.md"};function o(n,e,d,c,l,u){return s(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="desactiver-les-surcharges-d-image-des-entites" tabindex="-1">Désactiver les surcharges d&#39;image des entités <a class="header-anchor" href="#desactiver-les-surcharges-d-image-des-entites" aria-label="Permalink to &quot;Désactiver les surcharges d&#39;image des entités&quot;">​</a></h1><p>Par défaut, UIX corrige les badges et marqueurs standard de Home Assistant (<code>ha-entity-marker</code>, <code>ha-tile-icon</code>, <code>state-badge</code>, <code>ha-user-badge</code>, <code>ha-person-badge</code>) afin de permettre les surcharges d&#39;image personnalisées comme <code>--uix-image</code> ou <code>--uix-image-for-&lt;entity_id&gt;</code>. Cette option désactive cette correction pour améliorer le rendu sur les appareils peu puissants.</p><h2 id="reglage-depuis-l-interface-de-l-integration" tabindex="-1">Réglage depuis l&#39;interface de l&#39;intégration <a class="header-anchor" href="#reglage-depuis-l-interface-de-l-integration" aria-label="Permalink to &quot;Réglage depuis l&#39;interface de l&#39;intégration&quot;">​</a></h2><p>Cette option est <strong>désactivée par défaut</strong>. Pour l&#39;activer :</p><ol><li>Dans Home Assistant, ouvrez <strong>Paramètres → Appareils et services → UI eXtension → Configurer</strong>.</li><li>Sélectionnez <strong>Réglages de performance</strong>.</li><li>Activez <strong>Désactiver les surcharges d&#39;image des entités</strong>.</li><li>Enregistrez.</li></ol><p>Le réglage prend effet immédiatement dans toutes les sessions de navigateur connectées ; aucun rechargement n&#39;est nécessaire.</p><h2 id="comportement-lorsqu-elle-est-activee" tabindex="-1">Comportement lorsqu&#39;elle est activée <a class="header-anchor" href="#comportement-lorsqu-elle-est-activee" aria-label="Permalink to &quot;Comportement lorsqu&#39;elle est activée&quot;">​</a></h2><p>Lorsque cette option est activée :</p><ul><li>Les badges et marqueurs standard ne sont <strong>pas corrigés</strong> ni surveillés pour les propriétés d&#39;image personnalisées.</li><li>Les surcharges d&#39;image existantes via des variables CSS, par exemple <code>--uix-image</code> ou <code>--uix-image-for-*</code>, ne s&#39;appliquent <strong>pas</strong> aux badges ou marqueurs.</li></ul>',9)])])}const m=t(i,[["render",o]]);export{p as __pageData,m as default};
